cd /workspace/project && python3 - <<'EOF'
import pathlib
p=pathlib.Path('src/star4_switch.c')
s=p.read_text()
old="""        size_t want = (size_t)c->D * 4u;
        if (body == want) {
            out->payload = bth + 12;
            out->payload_len = want;
        } else if (body == want + 4u) {
            /* optional AETH ahead of the payload */
            out->payload = bth + 16;
            out->payload_len = want;
        } else {
            return 0;
        }"""
new="""        /* A DATA frame carries the vector payload directly behind the BTH:
         * its length is exactly 4D words and nothing else. */
        size_t want = (size_t)c->D * 4u;
        if (body != want) {
            return 0;
        }
        out->payload = bth + 12;
        out->payload_len = want;"""
assert old in s
p.write_text(s.replace(old,new))
print('patched')
EOF
cd /workspace/project && make BUILD=/tmp/b1 -j2 2>&1|tail -1 && cd /workspace && python3 public_check.py project/solver.py
